class Solution:
    def maximumValueSum(self, board: List[List[int]]) -> int:
        m, n = len(board), len(board[0])
        def topk(vals, k):
            return sorted(vals, reverse=True)[:k]
        rowTop = [topk([(board[i][j], j) for j in range(n)], 4) for i in range(m)]
        def merge(a, b, k):
            return topk(a + b, k)
        leftTop, cur = [], []
        for b in range(m):
            leftTop.append(topk(cur, 6))
            cur = merge(cur, rowTop[b], 6)
        rightTop, cur = [], []
        for b in range(m - 1, -1, -1):
            rightTop.append(topk(cur, 6))
            cur = merge(cur, rowTop[b], 6)
        rightTop.reverse()
        NEG = float('-inf')
        ans = NEG
        for b in range(m):
            L, R = leftTop[b], rightTop[b]
            for vb, jb in rowTop[b]:
                LA = [(v, j) for v, j in L if j != jb][:3]
                RA = [(v, j) for v, j in R if j != jb][:3]
                for va, ja in LA:
                    for vc, jc in RA:
                        if ja != jc:
                            ans = max(ans, va + vb + vc)
        return ans

