class Solution {
public:
    int maximumValueSum(vector<vector<int>>& board) {
        int m = board.size(), n = board[0].size();
        vector<vector<pair<int,int>>> rowTop(m);
        for (int i = 0; i < m; i++) {
            vector<pair<int,int>> v;
            for (int j = 0; j < n; j++) v.push_back({board[i][j], j});
            sort(v.begin(), v.end(), [](auto& a, auto& b){ return a.first > b.first; });
            v.resize(min(4, (int)v.size()));
            rowTop[i] = v;
        }
        auto mergeTop = [&](vector<pair<int,int>> a, vector<pair<int,int>> b, int k) {
            for (auto& p : b) a.push_back(p);
            sort(a.begin(), a.end(), [](auto& x, auto& y){ return x.first > y.first; });
            if ((int)a.size() > k) a.resize(k);
            return a;
        };
        vector<vector<pair<int,int>>> leftTop(m), rightTop(m);
        vector<pair<int,int>> cur;
        for (int b = 0; b < m; b++) {
            leftTop[b] = cur.size() > 6 ? vector<pair<int,int>>(cur.begin(), cur.begin() + 6) : cur;
            cur = mergeTop(cur, rowTop[b], 6);
        }
        cur.clear();
        for (int b = m - 1; b >= 0; b--) {
            rightTop[b] = cur.size() > 6 ? vector<pair<int,int>>(cur.begin(), cur.begin() + 6) : cur;
            cur = mergeTop(cur, rowTop[b], 6);
        }
        long long ans = LLONG_MIN;
        for (int b = 0; b < m; b++) {
            for (auto& [vb, jb] : rowTop[b]) {
                vector<pair<int,int>> LA, RA;
                for (auto& p : leftTop[b]) if (p.second != jb) { LA.push_back(p); if (LA.size() == 3) break; }
                for (auto& p : rightTop[b]) if (p.second != jb) { RA.push_back(p); if (RA.size() == 3) break; }
                for (auto& [va, ja] : LA)
                    for (auto& [vc, jc] : RA)
                        if (ja != jc) ans = max(ans, (long long)va + vb + vc);
            }
        }
        return (int)ans;
    }
};

