class Solution {
    public int maximumValueSum(int[][] board) {
        int m = board.length, n = board[0].length;
        int[][][] rowTop = new int[m][4][2];
        int[] rowTopLen = new int[m];
        for (int i = 0; i < m; i++) {
            List<int[]> v = new ArrayList<>();
            for (int j = 0; j < n; j++) v.add(new int[]{board[i][j], j});
            v.sort((a, b) -> b[0] - a[0]);
            rowTopLen[i] = Math.min(4, v.size());
            for (int k = 0; k < rowTopLen[i]; k++) rowTop[i][k] = v.get(k);
        }
        long ans = Long.MIN_VALUE;
        for (int b = 0; b < m; b++) {
            List<int[]> L = new ArrayList<>(), R = new ArrayList<>();
            for (int a = 0; a < b; a++)
                for (int k = 0; k < rowTopLen[a]; k++) L.add(rowTop[a][k]);
            for (int c = b + 1; c < m; c++)
                for (int k = 0; k < rowTopLen[c]; k++) R.add(rowTop[c][k]);
            L.sort((x, y) -> y[0] - x[0]); R.sort((x, y) -> y[0] - x[0]);
            for (int t = 0; t < rowTopLen[b]; t++) {
                int vb = rowTop[b][t][0], jb = rowTop[b][t][1];
                List<int[]> LA = new ArrayList<>(), RA = new ArrayList<>();
                for (int[] p : L) if (p[1] != jb && LA.size() < 3) LA.add(p);
                for (int[] p : R) if (p[1] != jb && RA.size() < 3) RA.add(p);
                for (int[] pa : LA) for (int[] pc : RA)
                    if (pa[1] != pc[1]) ans = Math.max(ans, (long) pa[0] + vb + pc[0]);
            }
        }
        return (int) ans;
    }
}

