var maximumValueSum = function(board) {
    const m = board.length, n = board[0].length;
    const rowTop = [];
    for (let i = 0; i < m; i++) {
        const v = board[i].map((x, j) => [x, j]);
        v.sort((a, b) => b[0] - a[0]);
        rowTop.push(v.slice(0, 4));
    }
    let ans = -Infinity;
    for (let b = 0; b < m; b++) {
        const L = [], R = [];
        for (let a = 0; a < b; a++) L.push(...rowTop[a]);
        for (let c = b + 1; c < m; c++) R.push(...rowTop[c]);
        L.sort((x, y) => y[0] - x[0]); R.sort((x, y) => y[0] - x[0]);
        for (const [vb, jb] of rowTop[b]) {
            const LA = L.filter(p => p[1] !== jb).slice(0, 3);
            const RA = R.filter(p => p[1] !== jb).slice(0, 3);
            for (const [va, ja] of LA)
                for (const [vc, jc] of RA)
                    if (ja !== jc) ans = Math.max(ans, va + vb + vc);
        }
    }
    return ans;
};
